import math

solutions = []

# Iterate through possible values for a, b, and c (1 to 6)
for a in range(1, 7):
    for b in range(1, 7):
        for c in range(1, 7):
            # Calculate both sides of the equation: 2^a + 3^b + 1 = 6^c
            left_side = 2**a + 3**b + 1
            right_side = 6**c

            if left_side == right_side:
                solutions.append((a, b, c))

print("Found solutions (a, b, c):", solutions)
